-- Machine learning experiment tracking: experiments, the training runs of each (model, hyperparameters, results) and the validation loss of some runs after every epoch.
-- Made by scripts/dev/make-sql-data.py: do not edit by hand.

CREATE TABLE experiments (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  task TEXT NOT NULL
);

CREATE TABLE runs (
  id INTEGER PRIMARY KEY,
  experiment_id INTEGER NOT NULL REFERENCES experiments(id),
  model TEXT NOT NULL,
  learning_rate REAL NOT NULL,
  batch_size INTEGER NOT NULL,
  val_accuracy REAL,  -- NULL when the run failed
  val_loss REAL,  -- NULL when the run failed
  train_seconds INTEGER NOT NULL,
  status TEXT NOT NULL  -- done or failed
);

CREATE TABLE metrics (
  run_id INTEGER NOT NULL REFERENCES runs(id),
  epoch INTEGER NOT NULL,
  val_loss REAL NOT NULL
);
